// @ts-check
import { existsSync, readFileSync } from 'node:fs';
import { defineConfig } from 'astro/config';
import starlight from '@astrojs/starlight';
import yaml from 'js-yaml';
import { SITE_URL } from './site.config.mjs';

const { books } = yaml.load(readFileSync(new URL('./books.yaml', import.meta.url), 'utf8'));

// Covers are generated by the export script and are not in git. Check them once, here,
// because bundled code cannot resolve paths relative to its own file.
const coverFiles = Object.fromEntries(
  books.map((book) => [
    book.slug,
    existsSync(new URL(`./public/books/${book.slug}/thumb-400x640.png`, import.meta.url)),
  ]),
);

// Book 1 gets its own sidebar group with every chapter. The others are listed once.
const otherBooks = books.filter((book) => book.number !== 1).map((book) => ({ slug: book.slug }));

export default defineConfig({
  site: SITE_URL,
  vite: {
    define: {
      __BOOKS__: JSON.stringify(books),
      __COVER_FILES__: JSON.stringify(coverFiles),
    },
  },
  integrations: [
    starlight({
      title: 'AI Engineering Library',
      description:
        'Books by Ravi Pal on applied AI engineering. Each book builds one real project with local models, one idea per chapter.',
      customCss: ['./src/styles/custom.css'],
      components: {
        // The site is light only, so the theme switch is not rendered.
        ThemeSelect: './src/components/NoThemeSelect.astro',
        // Adds the licence notice under every page.
        Footer: './src/components/Footer.astro',
      },
      expressiveCode: {
        themes: ['github-light'],
        // Plain-text blocks (data files, program output) wrap so they stay readable
        // on a phone. Python keeps its lines intact and scrolls, so indentation is never ambiguous.
        defaultProps: { overridesByLang: { 'text,txt,plaintext': { wrap: true, preserveIndent: true } } },
        styleOverrides: {
          codeBackground: '#F7F5EE',
          borderColor: '#D8D0BE',
          codeFontFamily: "'JetBrains Mono', Consolas, 'Courier New', monospace",
          codeFontSize: '0.875rem',
        },
      },
      sidebar: [
        { label: 'Reading guide', items: [{ slug: 'running-the-examples' }] },
        { label: 'Applied AI Engineering', items: [{ autogenerate: { directory: 'applied-ai-engineering' } }] },
        { label: 'More books in the series', collapsed: true, items: otherBooks },
      ],
      lastUpdated: false,
    }),
  ],
});
